nta.declaration:
const int n = 6;          // breytanlegt board siez
clock total_time;         // clock fyrir task 5
int movec = 0;

int[0,20] grid[n][n];    // í hverjum reit getur verið bíll með id, eða 0 sem er empty reitur

int total_moves = 0;

// Boolean fall sem skilar true ef id er á stað (x,y) og getur farið á næsta stað (dx, dy)
bool canMove(int id, int x, int y, int dx, int dy, int len, bool horiz, int steps) {
    int i;
    if (horiz) {
        // Fyrir lárétta bíla, tjekka hvort að allir næstu reitir eru lausir.
        // Ef hægri: dx > 0, skoða reiti x+len til x+len+steps-1
        // Ef vinstri: dx < 0, skoða reiti x-1 til x-steps
        for (i = 1; i <= steps; i++) {
            int nextX = (dx > 0) ? x + len + i - 1 : x - i;
            if (nextX < 0 || nextX >= n) return false;  // ef hann skildi fara útfyrir kassann
            if (grid[y][nextX] != 0) return false;       // ef einhver reitur á leiðinni er upptekinn
        }
        return true;  // allir reitir á leiðinni eru lausir
    } else {
        // sama fyrir lóðrétta bíla, nema með y
        for (i = 1; i <= steps; i++) {
            int nextY = (dy > 0) ? y + len + i - 1 : y - i;
            if (nextY < 0 || nextY >= n) return false;  // ef hann skildi fara útfyrir kassann
            if (grid[nextY][x] != 0) return false;       // ef einhver reitur á leiðinni er upptekinn
        }
        return true;  // allir reitir á leiðinni eru lausir
    }
}

void move_car(int id, int x, int y, int dx, int dy, int len, bool horiz, int steps) {
    int i;
    if (horiz) {
        if (dx > 0) {  // fer til hægri
            for (i = 0; i < len; i++) grid[y][x + i] = 0;          // tæmir alla gamla reiti
            for (i = 0; i < len; i++) grid[y][x + steps + i] = id; // fyllir alla nýja reiti
        } else if (dx < 0) {  // fer til vinstri
            for (i = 0; i < len; i++) grid[y][x + i] = 0;          // tæmir alla gamla reiti
            for (i = 0; i < len; i++) grid[y][x - steps + i] = id; // fyllir alla nýja reiti
        }
    } else {
        if (dy > 0) {  // fer niður
            for (i = 0; i < len; i++) grid[y + i][x] = 0;          // tæmir alla gamla reiti
            for (i = 0; i < len; i++) grid[y + steps + i][x] = id; // fyllir alla nýja reiti
        } else if (dy < 0) {  // fer upp
            for (i = 0; i < len; i++) grid[y + i][x] = 0;          // tæmir alla gamla reiti
            for (i = 0; i < len; i++) grid[y - steps + i][x] = id; // fyllir alla nýja reiti
        }
    }
}


// Stillir upp bílum frá Local Declarations í initializer með bíla ids
void place_car(int id, int len, int x, int y, bool horiz) {
    // mikilvægt að initializa rétt inn í local initializer
    int i;
    for (i = 0; i < len; i++) {
        if (horiz && x + i < n)      grid[y][x + i] = id;  // fer frá vinstri til hægri
        else if (!horiz && y + i < n) grid[y + i][x] = id; // fer frá topp niður að botn
    }
}

template.declaration:
// false = Vertical
// treu = Horizontal
void place_all() {
    place_car(1,  2, 3, 2, true);
    place_car(2,  2, 0, 0, true);
    place_car(3,  2, 2, 0, true); 
    place_car(4,  2, 4, 0, false); 
    place_car(5,  2, 2, 1, false); 
    place_car(6,  3, 5, 1, false);
    place_car(7,  2, 1, 2, false);
    place_car(8,  3, 0, 3, false);
    place_car(9,  2, 3, 3, true);
    place_car(10, 2, 3, 4, false);
    place_car(11, 2, 4, 4, true);
    place_car(12, 2, 1, 5, true);
    place_car(13, 2, 4, 5, true);
}

nta.system:
inits = initializer();
red = horizontalCar(1,  2, 3, 2);
car1 = horizontalCar(2,  2, 0, 0);
car2 = horizontalCar(3,  2, 2, 0);
car3 = verticalCar  (4,  2, 4, 0);
car4 = verticalCar  (5,  2, 2, 1);
truck1 = verticalCar  (6,  3, 5, 1);
car6 = verticalCar  (7,  2, 1, 2);
truck2 = verticalCar  (8,  3, 0, 3);
car7 = horizontalCar(9,  2, 3, 3);
car8 = verticalCar  (10, 2, 3, 4);
car9 = horizontalCar(11, 2, 4, 4);
car10 = horizontalCar(12, 2, 1, 5);
car11 = horizontalCar(13, 2, 4, 5);

system inits, red, car1, car2, car3, car4, truck1, car6, truck2, car7, car8, car9, car10, car11;
